def atlas(book,cell,label):
    return {'label':label,'image':f'assets/books/{book}/art/{book}-answers.webp','cell':cell}

def subject(book,name,label):
    return {'label':label,'image':f'assets/books/{book}/art/{book}-exact-{name}.webp'}

