def write_questions(book_id,rows,visuals):
    path=DATA/f'{book_id}.json'
    book=json.loads(path.read_text())
    untouched={k:v for k,v in book.items() if k!='questions'}
    questions=[]
    for i,(part,quote,prompt,correct,alternative,hint,feedback) in enumerate(rows):
        end=min((i//2+1)*3,len(book['pages']))-1
        start=end-(end%3)
        assert start<=part-1<=end,(book_id,i,part,start,end)
        page=book['pages'][part-1]
        assert quote in page['text'],(book_id,i,part,quote)
        qid=f'{book_id}-exact-question-{i+1:03d}'
        answer=i%2
        choices=[visuals[correct],visuals[alternative]]
        if answer: choices.reverse()
        for c in choices: assert (ROOT/c['image']).exists(),c['image']
        questions.append(dict(id=qid,afterPage=end,prompt=prompt,hint=hint,
            guided=f'Давай вместе. Нажми на картинку с зелёной рамкой. {feedback}',feedback=feedback,
            choices=choices,answer=answer,
            evidence=dict(pageIds=[page['id']],quote=quote),
            audio={kind:f'assets/books/{book_id}/audio/{qid}-{kind}.mp3' for kind in ('prompt','hint','guided','feedback')}))
    n=len(book['pages'])
    assert len(questions)==n//3*2+min(n%3,2)
    book['questions']=questions
    assert {k:v for k,v in book.items() if k!='questions'}==untouched
    path.write_text(json.dumps(book,ensure_ascii=False,indent=2)+'\n')
    print(book_id,len(questions),'questions; all exact evidence and image paths verified; narration preserved.')


if __name__=='__main__':
    write_questions('frog-princess',FROG,F)
    write_questions('ugly-duckling',DUCK,D)
